import{_ as e,o as a,c as o,a0 as n}from"./chunks/framework.BXmxXpv-.js";const _=JSON.parse('{"title":"智能计算系统实验室","titleTemplate":"电子科技大学","description":"","frontmatter":{"layout":"home","title":"智能计算系统实验室","titleTemplate":"电子科技大学","hero":{"name":"\\n智能计算系统实验室","tagline":"探界智能系统前沿 · 构筑未来计算生态<br>Next-generation Intelligent Systems Exploration","image":{"src":"/nise-logo.svg","alt":"ICSLab"}}},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md","lastUpdated":1783391508000}'),r={name:"zh/index.md"};function l(i,t,s,g,d,h){return a(),o("div",null,[...t[0]||(t[0]=[n('<h2 id="团队简介" tabindex="-1">团队简介 <a class="header-anchor" href="#团队简介" aria-label="Permalink to &quot;团队简介&quot;">​</a></h2><p>智能计算系统实验室是电子科技大学计算机科学与工程学院的实验室。团队成立于2018年1月，致力于无线系统及安全、无源系统、RFID技术、网络与系统安全、智能信息处理、数据挖掘与推荐、智能视频分析等方向的基础研究和相应系统研发。旨在聚焦前沿，引领未来，探索智能计算与物理世界深度融合的新范式，重点突破具身智能领域的核心理论与关键技术。研究团队包括教授博导1人，副教授1人，硕博研究生近30人。近五年，团队承担了多项国家自然科学基金、国家重点研发计划、国家科技支撑等项目。</p><p>在无源无线感知物联网系统、无线嵌入式系统、智能信息处理等方面取得了众多研究成果，构建了应用于结构体健康监测、可穿戴医疗设备、可穿戴远程健康监护等一系列实际系统和应用示范。在包括ACM/IEEE等著名Transactions期刊和国际顶级学术会议上发表论文，总数120余篇。团队具备齐全的研发设备和以及各类系统软件、应用软件和设计开发工具；提供了从感知前端设计、通信协议和系统、智能信息处理、云端系统、网络安全的完全研发链条。</p><h2 id="主要研究领域及方向" tabindex="-1">主要研究领域及方向 <a class="header-anchor" href="#主要研究领域及方向" aria-label="Permalink to &quot;主要研究领域及方向&quot;">​</a></h2><ul><li><strong>物联网边端体系与智能计算</strong>：面向具身智能的轻量化边缘智能算法与芯片设计，端-边-云协同计算架构与任务卸载策略，移动分析与机器学习在边缘端的应用。</li><li><strong>具身智能感知与交互</strong>：物理世界智能化感知，图像与视觉信息计算的认知机理，无源无线感知系统。</li><li><strong>集群协同智能与通信</strong>：面向集群协同的通信技术，分布式智能与协同决策，无线系统及网络安全。</li><li><strong>智能信息处理与系统应用</strong>：数据挖掘与推荐系统，智能数据分析，原型系统与应用示范。</li></ul><h2 id="代表性科研项目" tabindex="-1">代表性科研项目 <a class="header-anchor" href="#代表性科研项目" aria-label="Permalink to &quot;代表性科研项目&quot;">​</a></h2><ol><li><strong>国家自然科学基金</strong>，G05U21A20462，安全攸关的航空智能制造威胁监检测和动态自适防御研究，2022.01-2025.12，260万，主持</li><li><strong>横向</strong>，H04W240006，基于动力学的胸外心脏按压机制研究与精准复苏，2024.01-2025.10，49万，主持</li><li><strong>国家自然科学基金（2021及以后）</strong>，G0562572098，物联网无线总线理论与关键技术研究，2026.01-2029.12，主持</li><li><strong>国家自然科学基金</strong>，基于多组学时序性图神经网络的血栓-炎症模型在急性主动脉夹层早期诊断和危险分层中的机制研究与转化，2023/01- 2025/12，61万元（校内15.25万元），参与</li><li><strong>国家重点研发计划</strong>，G072021YFB3101303，隐私数据按需脱敏与评估关键技术研究，2021.12-2024.11，70万，参与</li><li><strong>国家自然科学基金</strong>，G0562472070，云边融合的分布式大规模图数据流计算方法，2025.01-2028.12，50万，主持</li></ol>',7)])])}const p=e(r,[["render",l]]);export{_ as __pageData,p as default};
